#!/usr/bin/env python3
"""Compare the result tables regenerated by effect_scale_mr_analysis.R with the committed tables.

usage: python tests/compare_regenerated_outputs.py [--committed-ref REF]

The committed tables were produced on macOS (arm64, R reference BLAS); CI regenerates them on Linux.
Floating-point results then differ in the last one or two of 15 significant digits, so these nine
tables cannot be required to be byte-identical across platforms. Every other tracked file is still
required to be byte-identical by the workflow.

For each table listed in TOLERANCE_TABLES, compared with the committed version (git show REF:path):
  exact  - column names and order, number and order of rows, text cells (identifiers, method names,
           scale assignments, discordance flags, booleans), positions of missing values, and integer
           columns (columns whose committed values are all integers);
  float  - |old - new| <= 2e-13 + 2e-14 * max(|old|, |new|), and identical when rounded to four decimal
           places and to four significant figures;
  zero   - columns named absolute_*_difference hold residuals that are zero in exact arithmetic:
           |old| <= 2e-13 and |new| <= 2e-13.
The tolerance was set from the first cross-platform run (17 Oct 2026, ubuntu-24.04): 92 differing
cells, largest absolute difference 1.07e-13, largest ratio of difference to tolerance 0.098. The
per-column maxima are printed on every run, pass or fail.
"""
import csv
import io
import math
import os
import re
import subprocess
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
TOLERANCE_TABLES = [
    "results/MR_rerun_egger_intercept.csv",
    "results/MR_rerun_five_estimators.csv",
    "results/MR_rerun_heterogeneity.csv",
    "results/calibration_reanalysis.csv",
    "results/invariance_MRPRESSO_unit_test.csv",
    "results/invariance_egger_unit_test.csv",
    "results/invariance_estimator_unit_test.csv",
    "results/invariance_heterogeneity_unit_test.csv",
    "results/repository_scale_reanalysis.csv",
]
ATOL, RTOL, ZERO = 2e-13, 2e-14, 2e-13
INT = re.compile(r"^[+-]?\d+$")


def as_float(s):
    try:
        x = float(s)
    except ValueError:
        return None
    return x if math.isfinite(x) else None


def committed(ref, rel):
    r = subprocess.run(["git", "-C", ROOT, "show", f"{ref}:{rel}"], capture_output=True, text=True, check=True)
    return list(csv.reader(io.StringIO(r.stdout)))


def compare(rel, ref):
    old = committed(ref, rel)
    with open(os.path.join(ROOT, rel), newline="") as f:
        new = list(csv.reader(f))
    errors, stats = [], {}
    if old[0] != new[0]:
        return [f"{rel}: header differs"], stats
    if len(old) != len(new):
        return [f"{rel}: {len(old) - 1} committed rows, {len(new) - 1} regenerated"], stats
    header = old[0]
    # integer columns: every non-empty committed value is an integer literal
    integer_cols = {c for j, c in enumerate(header)
                    if all(INT.match(r[j]) for r in old[1:] if len(r) > j and r[j] != "")
                    and any(len(r) > j and r[j] != "" for r in old[1:])}
    for i, (ro, rn) in enumerate(zip(old[1:], new[1:]), start=2):
        if len(ro) != len(rn):
            errors.append(f"{rel} line {i}: field count differs")
            continue
        for col, a, b in zip(header, ro, rn):
            if a == b:
                continue
            where = f"{rel} line {i}, {col}: {a!r} -> {b!r}"
            x, y = as_float(a), as_float(b)
            if x is None or y is None or a == "" or b == "" or col in integer_cols:
                errors.append(f"{where} (must be exact)")
                continue
            d = abs(x - y)
            if col.startswith("absolute_") and col.endswith("difference"):
                ratio = max(abs(x), abs(y)) / ZERO
                if ratio > 1:
                    errors.append(f"{where} (zero residual above {ZERO:g})")
            else:
                tol = ATOL + RTOL * max(abs(x), abs(y))
                ratio = d / tol
                if ratio > 1:
                    errors.append(f"{where} (|diff| {d:.3g} > tolerance {tol:.3g})")
                if f"{x:.4f}" != f"{y:.4f}" or f"{x:.4g}" != f"{y:.4g}":
                    errors.append(f"{where} (changes at reporting precision)")
            s = stats.setdefault(col, [0, 0.0, 0.0, 0.0])
            s[0] += 1
            s[1] = max(s[1], d)
            s[2] = max(s[2], d / max(abs(x), abs(y)) if max(abs(x), abs(y)) > 0 else 0.0)
            s[3] = max(s[3], ratio)
    return errors, stats


def main():
    ref = sys.argv[sys.argv.index("--committed-ref") + 1] if "--committed-ref" in sys.argv else "HEAD"
    all_errors, cells = [], 0
    print(f"{'table':44s} {'column':38s} {'cells':>5s} {'max abs':>10s} {'max rel':>10s} {'max/tol':>8s}")
    for rel in TOLERANCE_TABLES:
        errors, stats = compare(rel, ref)
        all_errors += errors
        if not stats and not errors:
            print(f"{os.path.basename(rel):44s} {'(byte-identical)':38s}")
        for col, (n, a, r, q) in stats.items():
            cells += n
            print(f"{os.path.basename(rel):44s} {col:38s} {n:5d} {a:10.3g} {r:10.3g} {q:8.3f}")
    if all_errors:
        print("\nFAILED:")
        print("\n".join(all_errors))
        sys.exit(1)
    print(f"\n{len(TOLERANCE_TABLES)} tables: structure, text, missing values and integers identical; "
          f"{cells} floating-point cells differ, all within tolerance and identical at reporting precision")


if __name__ == "__main__":
    main()
